style.css:
@-moz-document domain("github.com"), domain("codepen.io"), domain("replit.com"), domain("stackblitz.com"), url-prefix("https://vscode.dev/"), url-prefix("https://github.dev/"), url-prefix("https://codesandbox.io/") {
/* 
    === COLOR PALETTE REFERENCE ===
    --indigo-bg: #0a0a12;          Deep space background
    --indigo-base: #1a1a2e;         Base UI elements
    --indigo-border: #2a2a4a;       Borders and dividers
    --indigo-accent: #6366f1;       Primary indigo glow
    --indigo-deep: #4f46e5;         Darker indigo
    --indigo-light: #818cf8;        Lighter indigo
    --indigo-violet: #8b5cf6;       Violet complement
    --indigo-text: #d1d5db;         Main text color
    --indigo-subtle: #9ca3af;       Secondary text
    --indigo-purple: #a78bfa;       Purple highlights
  */

  /* === EDITOR CORE === */

  /* Main editor area - the canvas where code lives */
  .monaco-editor, 
  .editor-instance, 
  .blob-wrapper, 
  .code-view, 
  .cm-editor,
  .view-lines, 
  .editor-container,
  pre, 
  code {
    background-color: #0a0a12 !important;  /* Deep space background */
    color: #d1d5db !important;              /* Soft gray text */
    caret-color: #6366f1 !important;        /* Indigo cursor with mystical glow */
  }

  /* === TEXT SELECTION & HIGHLIGHTS === */

  /* When you select text with your mouse */
  .monaco-editor .selected-text, 
  .monaco-editor .selection, 
  ::selection {
    background-color: #6366f144 !important;  /* Indigo selection with 27% opacity */
  }

  /* Selection when editor is not focused */
  .monaco-editor .inactive-selection {
    background-color: #2a2a4a55 !important;  /* Muted border color */
  }

  /* Highlights matching selected text elsewhere */
  .monaco-editor .selectionHighlight {
    background-color: #6366f122 !important;  /* Very subtle indigo */
  }

  /* === WORD & SEARCH HIGHLIGHTS === */

  /* Highlight occurrences of word under cursor */
  .monaco-editor .wordHighlight { 
    background-color: #6366f122 !important; 
  }
  .monaco-editor .wordHighlightStrong { 
    background-color: #6366f133 !important; 
  }

  /* Find/search results highlighting */
  .monaco-editor .findMatch { 
    background-color: #8b5cf655 !important;  /* Violet for active match */
  }
  .monaco-editor .findMatchHighlight { 
    background-color: #8b5cf633 !important;  /* Subtle violet for other matches */
  }

  /* Hover tooltips and info */
  .monaco-editor .hoverHighlight { 
    background-color: #6366f122 !important; 
  }

  /* === GUTTER & LINE NUMBERS === */

  /* Line numbers on the left side */
  .monaco-editor .line-numbers, 
  .line-number, 
  .gutter-cell {
    color: #9ca3af !important;  /* Subtle gray */
  }

  /* Current line number (where cursor is) */
  .monaco-editor .line-numbers.active, 
  .line-number.active, 
  .gutter-cell.active {
    color: #818cf8 !important;  /* Light indigo to show active line */
  }

  /* The gutter area itself (margin where line numbers appear) */
  .monaco-editor .margin, 
  .editor-gutter, 
  .monaco-editor .margin-view-overlays {
    background-color: #0a0a12 !important;
  }

  /* === GIT DECORATIONS IN GUTTER === */

  /* Green bar for added lines */
  .monaco-editor .line-added { 
    background-color: #10b98144 !important; 
  }

  /* Yellow bar for modified lines */
  .monaco-editor .line-modified { 
    background-color: #f59e0b44 !important; 
  }

  /* Red bar for deleted lines indicator */
  .monaco-editor .line-deleted { 
    background-color: #ef444444 !important; 
  }

  /* === ERROR & WARNING INDICATORS === */

  /* Warning icon in gutter */
  .monaco-editor .warning-glyph { 
    color: #f59e0b !important;  /* Amber warning */
  }

  /* Error icon in gutter */
  .monaco-editor .error-glyph { 
    color: #ef4444 !important;  /* Red error */
  }

  /* Info icon in gutter */
  .monaco-editor .info-glyph { 
    color: #6366f1 !important;  /* Indigo info */
  }

  /* === SYNTAX HIGHLIGHTING === */
  /* This is where we paint different parts of code with different colors */

  /* Comments - the explanatory notes programmers leave */
  .token.comment, 
  .punctuation.definition.comment, 
  .comment, 
  .mtk6 {
    color: #9ca3af !important;       /* Muted gray so they don't distract */
    font-style: italic !important;   /* Italics help differentiate them */
  }

  /* Keywords - the fundamental building blocks like 'if', 'function', 'return' */
  .token.keyword, 
  .token.storage, 
  .token.storage.type, 
  .token.storage.modifier, 
  .token.variable.language.this, 
  .keyword, 
  .mtk12 {
    color: #6366f1 !important;  /* Primary indigo - these are VIPs */
    font-weight: 500 !important;
  }

  /* Strings - text in quotes like "hello world" */
  .token.string, 
  .punctuation.definition.string, 
  .string, 
  .mtk7 {
    color: #fbbf24 !important;  /* Warm amber - makes text content pop */
  }

  /* Numbers - any numeric values like 42, 3.14 */
  .token.number, 
  .constant.numeric, 
  .number, 
  .mtk8 {
    color: #818cf8 !important;  /* Light indigo - numbers get a cooler tone */
  }

  /* Constants - fixed values like 'true', 'false', 'null' */
  .token.constant, 
  .constant.language, 
  .support.constant, 
  .constant, 
  .mtk11 {
    color: #8b5cf6 !important;  /* Violet for language-level constants */
    font-weight: 500 !important;
  }

  /* Functions - callable blocks of code */
  .token.function, 
  .entity.name.function, 
  .support.function, 
  .function, 
  .mtk4 {
    color: #a78bfa !important;  /* Purple - functions are special and deserve it */
  }

  /* Variables - named storage locations */
  .token.variable, 
  .variable, 
  .mtk1 {
    color: #d1d5db !important;  /* Main text color - variables are the workhorses */
  }

  /* Properties - attributes of objects like 'user.name' */
  .token.property, 
  .variable.other.property, 
  .property {
    color: #f97316 !important;  /* Orange for properties */
  }

  /* Classes and Types - blueprints for creating objects */
  .token.class-name, 
  .entity.name.type, 
  .support.class, 
  .class-name, 
  .type, 
  .mtk5 {
    color: #6366f1 !important;  /* Primary indigo - classes are architectural */
    font-weight: 600 !important;
  }

  /* Inherited classes - showing parent-child relationships */
  .token.inherited-class, 
  .entity.other.inherited-class {
    color: #c084fc !important;  /* Lighter purple for inheritance */
  }

  /* Operators - symbols like +, -, *, = */
  .token.operator, 
  .operator, 
  .mtk10 {
    color: #e5e7eb !important;  /* Bright gray - they're structural */
  }

  /* Punctuation - commas, semicolons, dots */
  .token.punctuation, 
  .punctuation {
    color: #9ca3af !important;  /* Subtle - shouldn't dominate */
  }

  /* Braces and brackets - {}, [], () */
  .token.brace, 
  .meta.brace, 
  .punctuation.bracket, 
  .punctuation.accessor, 
  .brace, 
  .bracket {
    color: #818cf8 !important;  /* Light indigo for structure markers */
  }

  /* HTML/XML tags - like <div>, <span> */
  .token.tag, 
  .punctuation.definition.tag, 
  .entity.name.tag, 
  .tag, 
  .mtk14 {
    color: #8b5cf6 !important;  /* Violet for markup tags */
  }

  /* HTML/XML attributes - like 'class', 'id', 'href' */
  .token.attr-name, 
  .entity.other.attribute-name, 
  .attr-name, 
  .mtk15 {
    color: #fbbf24 !important;  /* Amber for attributes */
  }

  /* Invalid/error tokens - syntax that's wrong */
  .token.invalid, 
  .invalid {
    color: #ef4444 !important;        /* Red for errors */
    text-decoration: wavy underline !important;
  }

  /* Links and URLs */
  .token.link, 
  .markup.underline.link, 
  .string.other.link, 
  .link {
    color: #6366f1 !important;
    text-decoration: underline !important;
  }

  /* Markdown headings */
  .token.heading, 
  .markup.heading, 
  .heading {
    color: #8b5cf6 !important;
    font-weight: bold !important;
  }

  /* === UI ELEMENTS === */
  /* Everything that's not the code itself - the interface around it */

  /* === ACTIVITY BAR (Far left vertical bar with icons) === */
  .activity-bar, 
  .monaco-workbench .activitybar {
    background-color: #1a1a2e !important;   /* Base UI color */
    border-right: 1px solid #2a2a4a !important;
  }

  /* Notification badges on activity bar icons */
  .activity-bar .badge, 
  .monaco-workbench .activitybar .badge .badge-content {
    background-color: #6366f1 !important;  /* Indigo badge */
    color: #ffffff !important;
  }

  /* === SIDEBAR (File explorer, search, etc.) === */
  .sidebar, 
  .monaco-workbench .sidebar {
    background-color: #0f0f1a !important;  /* Slightly lighter than editor */
    border-right: 1px solid #2a2a4a !important;
    color: #d1d5db !important;
  }

  /* Sidebar section headers */
  .sidebar-header, 
  .monaco-workbench .sidebar .title-label {
    background-color: #1a1a2e !important;
    border-bottom: 1px solid #2a2a4a !important;
    color: #818cf8 !important;  /* Light indigo for headers */
  }

  /* === STATUS BAR (Bottom bar with info) === */
  .status-bar, 
  .monaco-workbench .statusbar {
    background-color: #1a1a2e !important;
    border-top: 1px solid #2a2a4a !important;
    color: #d1d5db !important;
  }

  /* Status bar items on hover */
  .status-bar-item:hover, 
  .monaco-workbench .statusbar-item:hover {
    background-color: #6366f133 !important;  /* Subtle indigo highlight */
  }

  /* === PANELS (Terminal, output, problems, etc.) === */
  .panel, 
  .monaco-workbench .panel {
    background-color: #0f0f1a !important;
    border-top: 1px solid #2a2a4a !important;
  }

  /* Active panel tab (the one you're viewing) */
  .panel-title.active, 
  .monaco-workbench .panel .panel-header .title.active {
    border-bottom: 2px solid #6366f1 !important;  /* Indigo underline */
    color: #d1d5db !important;
  }

  /* Inactive panel tabs */
  .panel-title, 
  .monaco-workbench .panel .panel-header .title {
    color: #9ca3af !important;
  }

  /* === EDITOR TABS (Open files at the top) === */
  .editor-group-header, 
  .monaco-workbench .editor-group-container .tabs-and-actions-container {
    background-color: #0f0f1a !important;
  }

  /* Individual tab styling */
  .tab, 
  .monaco-workbench .tab {
    border-right: 1px solid #2a2a4a !important;
    background-color: #0f0f1a !important;
    color: #9ca3af !important;
    border-bottom: 1px solid #2a2a4a !important;
  }

  /* Active tab (file you're currently editing) */
  .tab.active, 
  .monaco-workbench .tab.active {
    border-bottom: 2px solid #6366f1 !important;  /* Indigo indicator */
    background-color: #0a0a12 !important;         /* Matches editor */
    color: #d1d5db !important;
  }

  /* Tab hover effect */
  .tab:hover, 
  .monaco-workbench .tab:hover {
    background-color: #6366f122 !important;  /* Subtle indigo glow */
  }

  /* === FORM CONTROLS === */

  /* Text inputs and textareas */
  input, 
  textarea, 
  .monaco-inputbox .input {
    background-color: #0f0f1a !important;
    color: #d1d5db !important;
    border: 1px solid #2a2a4a !important;
  }

  /* Input focus state */
  input:focus, 
  textarea:focus, 
  .monaco-inputbox .input:focus {
    border-color: #6366f1 !important;  /* Indigo border when focused */
    outline: none !important;
    box-shadow: 0 0 0 1px #6366f1 !important;  /* Subtle glow */
  }

  /* Buttons */
  button, 
  .monaco-button {
    background-color: #1a1a2e !important;
    color: #d1d5db !important;
    border: 1px solid #2a2a4a !important;
  }

  /* Button hover effect */
  button:hover, 
  .monaco-button:hover {
    background-color: #6366f155 !important;  /* Indigo glow on hover */
    border-color: #6366f1 !important;
  }

  /* Primary action buttons */
  button.primary, 
  .monaco-button.primary {
    background-color: #6366f1 !important;
    color: #ffffff !important;
    border: none !important;
  }

  button.primary:hover, 
  .monaco-button.primary:hover {
    background-color: #4f46e5 !important;  /* Darker indigo on hover */
  }

  /* Dropdown selects */
  select, 
  .monaco-select-box {
    background-color: #0f0f1a !important;
    border: 1px solid #2a2a4a !important;
    color: #d1d5db !important;
  }

  /* === LISTS (File explorer, command palette, etc.) === */

  /* List item hover */
  .list-item:hover, 
  .monaco-list .list-row:hover {
    background-color: #1a1a2e !important;
  }

  /* Selected/focused list item */
  .list-item.selected, 
  .monaco-list .list-row.selected, 
  .monaco-list .list-row.focused {
    background-color: #6366f133 !important;  /* Indigo selection */
  }

  /* Highlighted text in search results */
  .list-item .highlight, 
  .monaco-list .list-row .highlight {
    color: #6366f1 !important;
    font-weight: 600 !important;
  }

  /* === SCROLLBARS === */

  /* Scrollbar track */
  ::-webkit-scrollbar {
    width: 12px !important;
    height: 12px !important;
  }

  ::-webkit-scrollbar-track {
    background: #0a0a12 !important;
  }

  /* Scrollbar thumb (the draggable part) */
  ::-webkit-scrollbar-thumb {
    background: #2a2a4a !important;
    border-radius: 6px !important;
  }

  /* Scrollbar thumb on hover */
  ::-webkit-scrollbar-thumb:hover {
    background: #6366f1 !important;  /* Indigo on hover */
  }

  /* === TERMINAL === */

  /* Terminal background and text */
  .terminal, 
  .xterm-viewport, 
  .xterm-rows {
    background-color: #0a0a12 !important;
    color: #d1d5db !important;
  }

  /* Terminal selection */
  .terminal .xterm-selection { 
    background-color: #6366f144 !important; 
  }

  /* Terminal ANSI colors - the 16 standard colors */
  .terminal .xterm-color-0 { color: #1e293b !important; }  /* Black */
  .terminal .xterm-color-1 { color: #ef4444 !important; }  /* Red */
  .terminal .xterm-color-2 { color: #10b981 !important; }  /* Green */
  .terminal .xterm-color-3 { color: #f59e0b !important; }  /* Yellow */
  .terminal .xterm-color-4 { color: #6366f1 !important; }  /* Blue (Indigo!) */
  .terminal .xterm-color-5 { color: #a78bfa !important; }  /* Magenta (Purple) */
  .terminal .xterm-color-6 { color: #8b5cf6 !important; }  /* Cyan (Violet) */
  .terminal .xterm-color-7 { color: #d1d5db !important; }  /* White */
  .terminal .xterm-color-8 { color: #64748b !important; }  /* Bright Black */
  .terminal .xterm-color-9 { color: #f87171 !important; }  /* Bright Red */
  .terminal .xterm-color-10 { color: #34d399 !important; } /* Bright Green */
  .terminal .xterm-color-11 { color: #fbbf24 !important; } /* Bright Yellow */
  .terminal .xterm-color-12 { color: #818cf8 !important; } /* Bright Blue */
  .terminal .xterm-color-13 { color: #c084fc !important; } /* Bright Magenta */
  .terminal .xterm-color-14 { color: #a78bfa !important; } /* Bright Cyan */
  .terminal .xterm-color-15 { color: #f1f5f9 !important; } /* Bright White */

  /* === TOOLTIPS & POPUPS === */

  /* Hover tooltips */
  .monaco-hover, 
  .tooltip {
    background-color: #1a1a2e !important;
    border: 1px solid #6366f1 !important;  /* Indigo border */
    color: #d1d5db !important;
  }

  /* Context menus */
  .monaco-menu, 
  .context-menu {
    background-color: #1a1a2e !important;
    border: 1px solid #2a2a4a !important;
  }

  .monaco-menu .monaco-action-bar .action-item:hover,
  .context-menu .menu-item:hover {
    background-color: #6366f133 !important;
  }

  /* === BREADCRUMBS (File path navigation) === */
  .monaco-breadcrumbs {
    background-color: #0f0f1a !important;
  }

  .monaco-breadcrumb-item {
    color: #9ca3af !important;
  }

  .monaco-breadcrumb-item:hover {
    color: #6366f1 !important;
  }

  /* === MINIMAP (Code overview on right side) === */
  .monaco-editor .minimap {
    background-color: #0f0f1a !important;
  }

  .monaco-editor .minimap-slider {
    background-color: #6366f133 !important;
  }

  .monaco-editor .minimap-slider:hover {
    background-color: #6366f155 !important;
  }
}
